<?php
if(!defined('SCHOOLOS_OPERATIONS_LIBRARY')){header('Location: index.php?s=operations&area=transport',true,302);exit;}
function tm_schema():array{return [
 "CREATE TABLE IF NOT EXISTS tm_drivers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,phone VARCHAR(40) NOT NULL,licence VARCHAR(100) NOT NULL,expires_on DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',UNIQUE KEY driver_account(tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_routes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,driver_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,fee_kobo BIGINT NOT NULL DEFAULT 0,gps_enabled TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,INDEX(tenant_id,driver_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_stops(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,route_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,position INT NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,UNIQUE KEY route_position(tenant_id,route_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,route_id BIGINT UNSIGNED NOT NULL,stop_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,route_id,status),INDEX(tenant_id,student_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_trips(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,route_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,driver_user_id BIGINT UNSIGNED NOT NULL,service_day DATE NOT NULL,direction VARCHAR(12) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'in_progress',started_at DATETIME NOT NULL,completed_at DATETIME NULL,UNIQUE KEY daily_trip(tenant_id,route_id,service_day,direction)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_passengers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,trip_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,stop_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',authorization_id BIGINT UNSIGNED NULL,identity_note VARCHAR(500) NULL,updated_at DATETIME NULL,UNIQUE KEY passenger_once(trip_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_gps(tenant_id BIGINT UNSIGNED NOT NULL,trip_id BIGINT UNSIGNED NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,accuracy_m INT NOT NULL,recorded_at DATETIME NOT NULL,PRIMARY KEY(tenant_id,trip_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS tm_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,trip_id BIGINT UNSIGNED NULL,kind VARCHAR(20) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,vehicle_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function tm_route(array $u,int $id):array{$r=op_own('tm_routes',$u,$id);if(!op_can($u,'transport_manager')){if(!op_can($u,'driver')||!g('SELECT id FROM tm_drivers WHERE tenant_id=? AND id=? AND user_id=? AND status=?',[$u['tenant_id'],$r['driver_id'],$u['id'],'active']))throw new RuntimeException('Route is not assigned to this driver.');}return $r;}
function tm_trip(array $u,int $id):array{$r=op_own('tm_trips',$u,$id);if(!op_can($u,'transport_manager')&&(!op_can($u,'driver')||(int)$r['driver_user_id']!==(int)$u['id']))throw new RuntimeException('Trip unavailable.');return $r;}
function tm_coord(string $v,int $limit):float{if(!preg_match('/^-?\d{1,3}(?:\.\d{1,7})?$/D',$v)||abs((float)$v)>$limit)throw new RuntimeException('Invalid coordinates.');return (float)$v;}
function tm_suggestions(array $u,float $lat,float $lng):array{op_need($u,'transport_manager');$rows=q("SELECT s.*,r.name route_name,v.capacity,(SELECT COUNT(*) FROM tm_assignments a WHERE a.tenant_id=r.tenant_id AND a.route_id=r.id AND a.status='active') occupied FROM tm_stops s JOIN tm_routes r ON r.id=s.route_id AND r.tenant_id=s.tenant_id JOIN vehicles v ON v.id=r.vehicle_id AND v.tenant_id=r.tenant_id WHERE s.tenant_id=? AND r.active=1 AND v.status='active' AND s.latitude IS NOT NULL AND s.longitude IS NOT NULL",[$u['tenant_id']])->fetchAll();$out=[];foreach($rows as $r){if((int)$r['occupied']>=(int)$r['capacity'])continue;$a=sin(deg2rad((float)$r['latitude']-$lat)/2)**2+cos(deg2rad($lat))*cos(deg2rad((float)$r['latitude']))*sin(deg2rad((float)$r['longitude']-$lng)/2)**2;$r['distance_km']=round(6371*2*asin(sqrt(min(1,max(0,$a)))),2);$out[]=$r;}usort($out,fn($a,$b)=>$a['distance_km']<=>$b['distance_km']);return array_slice($out,0,3);}
function tm_action(array $u,string $a):string{
 global $pdo;$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$manager=op_can($u,'transport_manager');
 if($a==='suggest'){$_SESSION['tm_suggestions']=tm_suggestions($u,tm_coord(op_text('latitude',20,true),90),tm_coord(op_text('longitude',20,true),180));return 'Nearest available stops suggested by straight-line distance, not road routing.';}
 if($a==='start'){
  $route=tm_route($u,op_id('route_id'));$direction=op_text('direction',12);if(!in_array($direction,['pickup','dropoff'],true))throw new RuntimeException('Invalid trip direction.');$pdo->beginTransaction();try{$r=q('SELECT * FROM tm_routes WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$route['id']])->fetch();$v=q('SELECT * FROM vehicles WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['vehicle_id']])->fetch();$d=q('SELECT * FROM tm_drivers WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['driver_id']])->fetch();if(!$d)throw new RuntimeException('Driver unavailable.');if(!$r['active']||$v['status']!=='active'||$d['status']!=='active'||$d['expires_on']<date('Y-m-d')||!g('SELECT id FROM users WHERE tenant_id=? AND id=? AND active=1',[$tid,$d['user_id']])||!g("SELECT user_id FROM op_roles WHERE tenant_id=? AND user_id=? AND capability='driver'",[$tid,$d['user_id']]))throw new RuntimeException('Check route, vehicle, active driver access and licence.');
   if(g("SELECT id FROM tm_trips WHERE tenant_id=? AND status='in_progress' AND (vehicle_id=? OR driver_user_id=?) LIMIT 1",[$tid,$v['id'],$d['user_id']]))throw new RuntimeException('Driver or vehicle already has an active trip.');$pupils=q("SELECT * FROM tm_assignments WHERE tenant_id=? AND route_id=? AND status='active' ORDER BY student_id",[$tid,$r['id']])->fetchAll();if(!$pupils||count($pupils)>(int)$v['capacity'])throw new RuntimeException('Trip requires a nonempty manifest within vehicle capacity.');q('INSERT INTO tm_trips(tenant_id,route_id,vehicle_id,driver_user_id,service_day,direction,started_at) VALUES(?,?,?,?,?,?,?)',[$tid,$r['id'],$v['id'],$d['user_id'],date('Y-m-d'),$direction,date('Y-m-d H:i:s')]);$id=(int)$pdo->lastInsertId();foreach($pupils as $p)q('INSERT INTO tm_passengers(tenant_id,trip_id,student_id,stop_id) VALUES(?,?,?,?)',[$tid,$id,$p['student_id'],$p['stop_id']]);$pdo->commit();return 'Trip started with a fixed manifest. GPS is optional and off unless explicitly enabled.';
  }catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if(in_array($a,['mark','finish','gps'],true)){
  $trip=tm_trip($u,op_id('trip_id'));$pdo->beginTransaction();try{$t=q('SELECT * FROM tm_trips WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$trip['id']])->fetch();if($t['status']!=='in_progress')throw new RuntimeException('Trip is closed.');
   if($a==='finish'){if(g("SELECT id FROM tm_passengers WHERE tenant_id=? AND trip_id=? AND status='pending' LIMIT 1",[$tid,$t['id']]))throw new RuntimeException('Record every passenger before completing the trip.');q("UPDATE tm_trips SET status='completed',completed_at=? WHERE tenant_id=? AND id=?",[date('Y-m-d H:i:s'),$tid,$t['id']]);}
   elseif($a==='gps'){$r=op_own('tm_routes',$u,(int)$t['route_id']);if(!$r['gps_enabled']||(!$manager&&(int)$t['driver_user_id']!==$uid))throw new RuntimeException('GPS reporting is disabled/unavailable.');$lat=tm_coord(op_text('latitude',20,true),90);$lng=tm_coord(op_text('longitude',20,true),180);$accuracy=op_id('accuracy');if($accuracy>1000)throw new RuntimeException('Location accuracy must be within 1000 metres.');$old=q('SELECT recorded_at FROM tm_gps WHERE tenant_id=? AND trip_id=?',[$tid,$t['id']])->fetch();if($old&&strtotime($old['recorded_at'])>time()-15)throw new RuntimeException('Wait at least 15 seconds between reports.');q('INSERT INTO tm_gps(tenant_id,trip_id,latitude,longitude,accuracy_m,recorded_at) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE latitude=VALUES(latitude),longitude=VALUES(longitude),accuracy_m=VALUES(accuracy_m),recorded_at=VALUES(recorded_at)',[$tid,$t['id'],$lat,$lng,$accuracy,date('Y-m-d H:i:s')]);}
   else{$sid=op_id('student_id');$p=q('SELECT * FROM tm_passengers WHERE tenant_id=? AND trip_id=? AND student_id=? FOR UPDATE',[$tid,$t['id'],$sid])->fetch();if(!$p||$p['status']!=='pending')throw new RuntimeException('Passenger unavailable/already recorded.');$status=op_text('status',20);$allowed=$t['direction']==='pickup'?['boarded','absent']:['handed_over','absent'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid passenger state.');$auth=null;$note=op_text('identity_note',500);
    if($status==='handed_over'){$auth=op_id('authorization_id');$authorization=q("SELECT * FROM pp_requests WHERE tenant_id=? AND id=? AND student_id=? AND kind='pickup' FOR UPDATE",[$tid,$auth,$sid])->fetch();if(!$authorization||$authorization['status']!=='approved'||$authorization['starts_on']!==date('Y-m-d')||$t['service_day']!==date('Y-m-d')||op_text('identity_checked',10)!=='yes'||mb_strlen($note)<8)throw new RuntimeException('A current approved pickup authorization and physical identity check are required.');q("UPDATE pp_requests SET status='collected',reviewed_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$auth]);}
    if($status==='absent'&&mb_strlen($note)<3)throw new RuntimeException('Record a reason for absence.');q('UPDATE tm_passengers SET status=?,authorization_id=?,identity_note=?,updated_at=? WHERE tenant_id=? AND id=?',[$status,$auth?:null,$note,date('Y-m-d H:i:s'),$tid,$p['id']]);op_notify($u,$sid,'transport','Transport '.$t['direction'].': '.$status.' at '.date('H:i').' (Africa/Lagos).','TM-'.$t['id'].'-'.$sid);audit('transport.passenger.'.$status,'student',(string)$sid);
   }$pdo->commit();return 'Trip record updated. Notifications are in-app; no SMS or WhatsApp was sent.';
  }catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='event'){$v=op_own('vehicles',$u,op_id('vehicle_id'));$trip=op_id('trip_id');if(!$manager){$t=tm_trip($u,$trip);if((int)$t['vehicle_id']!==(int)$v['id'])throw new RuntimeException('Vehicle is not on your trip.');}elseif($trip){$t=tm_trip($u,$trip);if((int)$t['vehicle_id']!==(int)$v['id'])throw new RuntimeException('Vehicle/trip mismatch.');}$kind=op_text('kind',20);if(!in_array($kind,['maintenance','incident'],true))throw new RuntimeException('Invalid event.');q('INSERT INTO tm_events(tenant_id,vehicle_id,trip_id,kind,title,body,created_by) VALUES(?,?,?,?,?,?,?)',[$tid,$v['id'],$trip?:null,$kind,op_text('title',200,true),op_text('body',3000,true),$uid]);return 'Transport event recorded for review.';}
 op_need($u,'transport_manager');
 if($a==='vehicle'){$capacity=op_id('capacity');if($capacity<1||$capacity>100)throw new RuntimeException('Capacity must be 1–100.');q("INSERT INTO vehicles(tenant_id,name,plate_no,capacity,status) VALUES(?,?,?,?,'active')",[$tid,op_text('name',120,true),op_text('plate_no',40,true),$capacity]);return 'Vehicle registered.';}
 if($a==='vehicle_status'){$status=op_text('status',20);if(!in_array($status,['active','maintenance','inactive'],true))throw new RuntimeException('Invalid vehicle state.');$pdo->beginTransaction();try{$v=q('SELECT * FROM vehicles WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,op_id('vehicle_id')])->fetch();if(!$v)throw new RuntimeException('Vehicle unavailable.');if(g("SELECT id FROM tm_trips WHERE tenant_id=? AND vehicle_id=? AND status='in_progress'",[$tid,$v['id']]))throw new RuntimeException('Complete the active trip before changing vehicle state.');q('UPDATE vehicles SET status=? WHERE tenant_id=? AND id=?',[$status,$tid,$v['id']]);$pdo->commit();return 'Vehicle state updated.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='driver_update'){$d=op_own('tm_drivers',$u,op_id('driver_id'));$status=op_text('status',20);if(!in_array($status,['active','inactive'],true))throw new RuntimeException('Invalid driver state.');$pdo->beginTransaction();try{q('SELECT id FROM tm_drivers WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$d['id']]);if(g("SELECT id FROM tm_trips WHERE tenant_id=? AND driver_user_id=? AND status='in_progress'",[$tid,$d['user_id']]))throw new RuntimeException('Complete the active driver trip first.');q('UPDATE tm_drivers SET phone=?,licence=?,expires_on=?,status=? WHERE tenant_id=? AND id=?',[op_text('phone',40,true),op_text('licence',100,true),op_date(op_text('expires_on',10,true)),$status,$tid,$d['id']]);$pdo->commit();return 'Driver licence/contact/status updated.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='route_settings'){$pdo->beginTransaction();try{$r=q('SELECT * FROM tm_routes WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,op_id('route_id')])->fetch();if(!$r)throw new RuntimeException('Route unavailable.');q('SELECT id FROM vehicles WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['vehicle_id']]);q('SELECT id FROM tm_drivers WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['driver_id']]);if(g("SELECT id FROM tm_trips WHERE tenant_id=? AND route_id=? AND status='in_progress'",[$tid,$r['id']]))throw new RuntimeException('Complete the active route trip first.');$active=op_text('active',1)==='1'?1:0;if($active&&g('SELECT id FROM tm_routes WHERE tenant_id=? AND id<>? AND active=1 AND (vehicle_id=? OR driver_id=?) AND start_time<? AND end_time>? LIMIT 1',[$tid,$r['id'],$r['vehicle_id'],$r['driver_id'],$r['end_time'],$r['start_time']]))throw new RuntimeException('Reactivation conflicts with another route schedule.');$gps=isset($_POST['gps_enabled'])?1:0;q('UPDATE tm_routes SET active=?,gps_enabled=?,fee_kobo=? WHERE tenant_id=? AND id=?',[$active,$gps,op_money(op_text('fee',20,true),true),$tid,$r['id']]);if(!$gps)q('DELETE g FROM tm_gps g JOIN tm_trips t ON t.id=g.trip_id AND t.tenant_id=g.tenant_id WHERE t.tenant_id=? AND t.route_id=?',[$tid,$r['id']]);$pdo->commit();return 'Route settings updated; disabling GPS removes retained route coordinates.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='driver'){$account=op_own('users',$u,op_id('user_id'));if(!in_array($account['role'],['staff','teacher'],true)||!$account['active']||!g("SELECT user_id FROM op_roles WHERE tenant_id=? AND user_id=? AND capability='driver'",[$tid,$account['id']]))throw new RuntimeException('Grant driver access to an active employee account first.');q('INSERT INTO tm_drivers(tenant_id,user_id,name,phone,licence,expires_on) VALUES(?,?,?,?,?,?)',[$tid,$account['id'],op_text('name',180,true),op_text('phone',40,true),op_text('licence',100,true),op_date(op_text('expires_on',10,true))]);return 'Driver registered with an explicitly linked account.';}
 if($a==='route'){
  $v=op_own('vehicles',$u,op_id('vehicle_id'));$d=op_own('tm_drivers',$u,op_id('driver_id'));$start=op_time(op_text('start_time',5,true));$end=op_time(op_text('end_time',5,true));if($end<=$start)throw new RuntimeException('Route end must follow start on the same day.');$pdo->beginTransaction();try{q('SELECT id FROM vehicles WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$v['id']]);q('SELECT id FROM tm_drivers WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$d['id']]);if(g('SELECT id FROM tm_routes WHERE tenant_id=? AND active=1 AND (vehicle_id=? OR driver_id=?) AND start_time<? AND end_time>? LIMIT 1',[$tid,$v['id'],$d['id'],$end,$start]))throw new RuntimeException('Vehicle/driver daily time slot overlaps.');q('INSERT INTO tm_routes(tenant_id,vehicle_id,driver_id,name,start_time,end_time,fee_kobo,gps_enabled) VALUES(?,?,?,?,?,?,?,?)',[$tid,$v['id'],$d['id'],op_text('name',180,true),$start,$end,op_money(op_text('fee',20,true),true),isset($_POST['gps_enabled'])?1:0]);$pdo->commit();return 'Route created with scheduling checks.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='stop'){$r=op_own('tm_routes',$u,op_id('route_id'));$position=op_id('position');if($position<1||$position>500)throw new RuntimeException('Stop sequence must be 1–500.');$lat=op_text('latitude',20);$lng=op_text('longitude',20);if(($lat==='')!==($lng===''))throw new RuntimeException('Enter both coordinates or neither.');q('INSERT INTO tm_stops(tenant_id,route_id,name,position,latitude,longitude) VALUES(?,?,?,?,?,?)',[$tid,$r['id'],op_text('name',180,true),$position,$lat===''?null:tm_coord($lat,90),$lng===''?null:tm_coord($lng,180)]);return 'Route stop saved.';}
 if($a==='assign'||$a==='release'){
  $s=op_own('students',$u,op_id('student_id'));$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$s['id']]);$old=q("SELECT * FROM tm_assignments WHERE tenant_id=? AND student_id=? AND status='active' FOR UPDATE",[$tid,$s['id']])->fetch();if($a==='release'){if(!$old)throw new RuntimeException('No active assignment.');q('SELECT id FROM tm_routes WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$old['route_id']]);q("UPDATE tm_assignments SET status='released' WHERE tenant_id=? AND id=?",[$tid,$old['id']]);}
   else{if($old)throw new RuntimeException('Release the existing route assignment first.');$r=q('SELECT r.*,v.capacity FROM tm_routes r JOIN vehicles v ON v.id=r.vehicle_id AND v.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.id=? AND r.active=1 FOR UPDATE',[$tid,op_id('route_id')])->fetch();if(!$r)throw new RuntimeException('Route unavailable.');$stop=op_own('tm_stops',$u,op_id('stop_id'));if((int)$stop['route_id']!==(int)$r['id'])throw new RuntimeException('Stop is on a different route.');if((int)g("SELECT COUNT(*) FROM tm_assignments WHERE tenant_id=? AND route_id=? AND status='active'",[$tid,$r['id']])>=(int)$r['capacity'])throw new RuntimeException('Route vehicle is full.');q('INSERT INTO tm_assignments(tenant_id,route_id,stop_id,student_id) VALUES(?,?,?,?)',[$tid,$r['id'],$stop['id'],$s['id']]);}$pdo->commit();return 'Student route assignment updated; trip snapshots remain unchanged.';
  }catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='fee'){$s=op_own('students',$u,op_id('student_id'));$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$s['id']]);$r=q("SELECT r.* FROM tm_routes r JOIN tm_assignments a ON a.route_id=r.id AND a.tenant_id=r.tenant_id WHERE a.tenant_id=? AND a.student_id=? AND a.status='active'",[$tid,$s['id']])->fetch();if(!$r)throw new RuntimeException('Active route assignment required.');op_fee($u,(int)$s['id'],'TM',op_text('period',40,true),(int)$r['fee_kobo'],'Transport: '.$r['name']);$pdo->commit();return 'Transport fee generated once in existing Finance.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='close_event'){op_own('tm_events',$u,op_id('event_id'));q("UPDATE tm_events SET status='closed' WHERE tenant_id=? AND id=?",[$tid,op_id('event_id')]);return 'Transport event closed.';}
 throw new RuntimeException('Unsupported transport action.');
}
function tm_render(array $u):void{
 $tid=(int)$u['tenant_id'];$manager=op_can($u,'transport_manager');$driver=op_can($u,'driver');
 if(in_array($u['role'],['parent','student'],true)){
  foreach(op_children($u) as $s){op_card($s['name'].' — transport');op_table(q("SELECT r.name route,s.name stop,r.start_time,r.end_time FROM tm_assignments a JOIN tm_routes r ON r.id=a.route_id AND r.tenant_id=a.tenant_id JOIN tm_stops s ON s.id=a.stop_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.student_id=? AND a.status='active'",[$tid,$s['id']])->fetchAll(),['Route','Stop','Start','End']);op_table(q("SELECT t.service_day,t.direction,p.status,p.updated_at FROM tm_passengers p JOIN tm_trips t ON t.id=p.trip_id AND t.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.student_id=? ORDER BY t.id DESC LIMIT 30",[$tid,$s['id']])->fetchAll(),['Day','Journey','Status','Recorded']);echo '<p>Fees and receipts are in Family Space. Submit pickup authorizations there before a drop-off. Location coordinates and other passengers are private.</p></section>'; }return;
 }
 if(!$manager&&!$driver){op_card('Transport access');echo '<p>Ask your school administrator for transport manager or driver access.</p></section>';return;}
 $tabs=$manager?['vehicles'=>'Vehicles','drivers'=>'Drivers','routes'=>'Routes & stops','assignments'=>'Student assignments','fees'=>'Fees','trips'=>'Manifests & driver interface','events'=>'Maintenance & incidents','suggestions'=>'Route suggestions']:['trips'=>'Assigned routes & manifests','events'=>'Report an incident'];
 $view=is_string($_GET['view']??null)?$_GET['view']:'trips';if(!isset($tabs[$view]))$view='trips';echo '<nav class="op-nav">';foreach($tabs as $k=>$v)echo '<a href="?s=operations&amp;area=transport&amp;view='.$k.'">'.e($v).'</a>';echo '</nav>';op_card($tabs[$view]);
 $vehicles=$manager?q('SELECT id,name FROM vehicles WHERE tenant_id=?',[$tid])->fetchAll():q('SELECT DISTINCT v.id,v.name FROM vehicles v JOIN tm_trips t ON t.vehicle_id=v.id AND t.tenant_id=v.tenant_id WHERE t.tenant_id=? AND t.driver_user_id=?',[$tid,$u['id']])->fetchAll();$vc=op_choices($vehicles);
 $routes=$manager?q('SELECT * FROM tm_routes WHERE tenant_id=?',[$tid])->fetchAll():q("SELECT r.* FROM tm_routes r JOIN tm_drivers d ON d.id=r.driver_id AND d.tenant_id=r.tenant_id WHERE r.tenant_id=? AND d.user_id=? AND d.status='active'",[$tid,$u['id']])->fetchAll();$rc=op_choices($routes);
 $trips=$manager?q('SELECT * FROM tm_trips WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll():q('SELECT * FROM tm_trips WHERE tenant_id=? AND driver_user_id=? ORDER BY id DESC LIMIT 100',[$tid,$u['id']])->fetchAll();$tc=[];foreach($trips as $t)$tc[$t['id']]='#'.$t['id'].' '.$t['service_day'].' '.$t['direction'].' '.$t['status'];
 if($view==='vehicles'){
